// @layer core — the emitted source of the app export's route matcher.
//
// GENERATED by scripts/generate-export-router.ts from core/route-matcher.ts.
// Do not hand-edit: edit the kernel's matcher and run `deno task router:generate`.
// core/export-router_test.ts fails if the two drift.
//
// Emitted as its own file, `router.ts`, rather than inlined into main.ts for one reason
// that matters: the differential gate can import the artifact that actually ships and
// compare it against Hono without booting PGlite. One copy, gated against the real thing.

export const ROUTER_PATH = "router.ts";

export function generateRouterRuntimeSource(): string {
  return `// The exported app's route matcher, on URLPattern — a web standard, global in Deno
// and in Node 24+. This shell used to be a Hono app; this file is what replaced its
// routing, and every behaviour below was MEASURED against Hono 4 rather than assumed.
// core/export-router_test.ts is the gate: it loads THIS emitted file,
// registers the same table with real Hono, and compares answers over the routes the
// field uses, a precedence corpus and a seeded fuzz.

export interface RouteDef {
  method: string;
  path: string;
  handlerName: string;
}

// Generic over the route so a caller gets its OWN entry back on a hit, not a name it
// then has to look up. What the preview actually needs off a hit is the route's METHOD
// and PATH as well as its handler — they key its validator map and label its request log
// — and a bare handler name would mean a second lookup to recover them. The kernel's
// RouteEntry satisfies RouteDef structurally, so a caller can pass its own entries in
// and get them back.
export type CompiledRoute<T extends RouteDef = RouteDef> = T & {
  pattern: URLPattern;
};

export interface MatchResult<T extends RouteDef = RouteDef> {
  status: number;
  route: CompiledRoute<T> | null;
  params: Record<string, string>;
}

// Kernel path DSL -> URLPattern pathname. Three translations, all measured:
//
//  1. Hono's brace-delimited regex constraint \`:id{[0-9]+}\` -> \`:id([0-9]+)\`, scanned
//     with BALANCED braces. \`:id{\\d{2}}\` is a real pattern and a lazy \`[^}]*\` stops at
//     the inner brace, emitting \`:id(\\d{2)}\` — which URLPattern rejects outright.
//  2. A NON-TERMINAL \`*\` matches exactly ONE segment in Hono, possibly EMPTY, but is
//     greedy across segments in URLPattern: \`/x/*/y\` accepts \`/x/a/b/y\` under
//     URLPattern and 404s under Hono, while \`/1//e\` matches \`/:a/*/:id\` under Hono and
//     not under a \`[^/]+\` group. So it becomes \`[^/]*\` — one segment, empty allowed.
//  3. A TERMINAL \`*\` is multi-segment in both, but Hono also matches the bare parent:
//     \`/new\` hits \`/new/*\`, and \`/ü\` hits \`/:slug/*\`. URLPattern's \`/new/*\` requires
//     the slash, so the whole \`/…/*\` tail becomes optional: \`{/*}?\`.
//
// (2) and (3) were found by fuzzing, not by reading: every wildcard in the
// hand-written corpus was terminal AND probed with a trailing segment present.
//
// ONE PASS, not a brace pass followed by a \`/\\*/g\` replace, because a constraint can
// contain a \`*\` of its own (\`:id{[0-9]*}\`) and a second pass over the whole string
// rewrites it into nonsense. Scanning once means a constraint body is copied through
// untouched by construction.
export function toPatternPath(path: string): string {
  let out = "";
  let tail = "";
  let wild = 0;
  let i = 0;
  while (i < path.length) {
    const m = /^:(\\w+)\\{/.exec(path.slice(i));
    if (m) {
      let j = i + m[0].length;
      let depth = 1;
      while (j < path.length && depth > 0) {
        if (path[j] === "{") depth++;
        else if (path[j] === "}") depth--;
        if (depth > 0) j++;
      }
      if (depth !== 0) {
        // Unbalanced: leave the rest alone and let URLPattern complain by name.
        out += path.slice(i);
        break;
      }
      out += \`:\${m[1]}(\${path.slice(i + m[0].length, j)})\`;
      i = j + 1;
      continue;
    }
    if (path[i] === "*") {
      if (i === path.length - 1) {
        if (out.endsWith("/")) {
          out = out.slice(0, -1);
          tail = "{/*}?";
        } else {
          tail = "*";
        }
      } else {
        out += \`:__w\${wild++}([^/]*)\`;
      }
      i++;
      continue;
    }
    out += path[i]!;
    i++;
  }
  return out + tail;
}

// NO specificity sort. Measured: Hono 4's SmartRouter resolves by REGISTRATION ORDER
// alone — first matching pattern wins. A static \`/api/items/new\` registered after
// \`/api/items/:id\` loses to it, and a wildcard registered before a static sibling
// beats it. Ranking static above param — the obvious design — diverges from the
// exported app's own behaviour on exactly those routes. The order is stable because
// the export pre-sorts the route table.
export function compileRoutes<T extends RouteDef>(
  routes: readonly T[],
): CompiledRoute<T>[] {
  return routes.map((r) => ({
    ...r,
    pattern: new URLPattern({ pathname: toPatternPath(r.path) }),
  }));
}

// Hono percent-decodes param values; URLPattern hands back the raw segment. A
// malformed sequence (%ZZ) makes decodeURIComponent throw, so fall back to raw.
function decodeParam(value: string): string {
  if (!value.includes("%")) return value;
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

export function match<T extends RouteDef>(
  compiled: readonly CompiledRoute<T>[],
  method: string,
  path: string,
): MatchResult<T> {
  // The method is compared VERBATIM. The fetch spec normalises only
  // DELETE/GET/HEAD/OPTIONS/POST/PUT, so a request built with "patch" keeps the
  // lowercase spelling and Hono does not match it. Upper-casing here would make the
  // exported app accept requests the current one rejects.
  //
  // HEAD is dispatched AS GET, before routing: \`HEAD /x\` runs the GET handler for \`/x\`
  // and a route registered under HEAD is unreachable. Measured — it is why this is not
  // "the same method, or GET when the method is HEAD".
  const wanted = method === "HEAD" ? "GET" : method;
  const acceptable = (routeMethod: string): boolean => {
    const rm = routeMethod.toUpperCase();
    return rm === "ALL" || rm === wanted;
  };

  const url = \`http://localhost\${path}\`;

  for (const route of compiled) {
    if (!acceptable(route.method)) continue;
    const hit = route.pattern.exec(url);
    if (!hit) continue;
    const params: Record<string, string> = {};
    for (const [k, v] of Object.entries(hit.pathname.groups)) {
      // Numeric keys are URLPattern's positional captures (the terminal \`*\`
      // remainder) and \`__w*\` are the synthesised non-terminal wildcards. Hono's
      // c.req.param() exposes neither.
      if (v === undefined || /^\\d+$/.test(k) || k.startsWith("__w")) continue;
      params[k] = decodeParam(v);
    }
    return { status: 200, route, params };
  }

  // Hono NEVER returned 405 here: a path registered under a different method 404d
  // exactly like an unregistered one. The matcher still reports the miss as a plain
  // 404 — deciding between 404 and 405 needs allowedMethods() below, and belongs to
  // the shell that writes the response, not to matching.
  return { status: 404, route: null, params: {} };
}

// The methods a path IS registered under, for the Allow header on a 405. Deliberately
// blind to the request method — a miss needs to know whether the path exists at all.
// An ALL route can never show up here: match() accepts every method for one, so a path
// carrying an ALL route never reaches the miss path to ask.
export function allowedMethods(
  compiled: readonly CompiledRoute[],
  path: string,
): string[] {
  const url = \`http://localhost\${path}\`;
  const out: string[] = [];
  for (const route of compiled) {
    const method = route.method.toUpperCase();
    if (method === "ALL" || out.includes(method)) continue;
    if (route.pattern.exec(url)) out.push(method);
  }
  return out;
}
`;
}
